{
  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])

    # Build node dict and children map
    nodes_by_id = {}
    children = {}
    for node in nodes:
        nid = node['id']
        nodes_by_id[nid] = node
        children[nid] = []

    # Build children lists and validate parent references
    root_id = None
    for node in nodes:
        nid = node['id']
        parent = node.get('parent')
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            if parent not in nodes_by_id:
                raise ValueError(f'Parent {parent} not found')
            children[parent].append(nid)

    if root_id is None:
        raise ValueError('No root node')

    # Validate required symbols exist
    symbols_present = {node['symbol'] for node in nodes}
    for sym in required_symbols:
        if sym not in symbols_present:
            raise ValueError(f'Required symbol {sym} not present')

    # Start with all nodes retained
    retained = set(nodes_by_id.keys())

    # Order nodes: deeper depth first, then by node ID ascending
    sorted_ids = sorted(
        nodes_by_id.keys(),
        key=lambda nid: (-nodes_by_id[nid]['depth'], nid)
    )

    removal_order = []
    for nid in sorted_ids:
        node = nodes_by_id[nid]
        if not node['removable']:
            continue
        if node['symbol'] in required_symbols:
            continue
        # Check if any child is still retained
        if any(child in retained for child in children[nid]):
            continue
        # Remove this node
        retained.remove(nid)
        removal_order.append(nid)

    retained_ids = sorted(retained)
    return {
        'retained_ids': retained_ids,
        'removal_order': removal_order
    }"
}
